import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class KeyPairTest {

    @Mock
    private EdDSAPublicKey publicKey;

    @Test
    public void constructor_givenPublicKey_whenCreated_thenPublicKeyReturned() {
        // Arrange
        KeyPair keyPair = new KeyPair(publicKey);

        // Assert
        assertEquals(publicKey, keyPair.getPublic());
    }

    @Test
    public void canSign_givenSignatureHint_whenVerifiedThenTrue() {
        // Arrange
        SignatureHint signatureHint = Mockito.mock(SignatureHint.class);
        when(signatureHint.getValidUntil()).thenReturn(1000);

        KeyPair keyPair = new KeyPair(publicKey);

        // Act
        boolean result = keyPair.canSign(signatureHint);

        // Assert
        assertTrue(result);
    }

    @Test
    public void canSign_givenSignatureHint_whenNotVerifiedThenFalse() {
        // Arrange
        SignatureHint signatureHint = Mockito.mock(SignatureHint.class);
        when(signatureHint.getValidUntil()).thenReturn(0);

        KeyPair keyPair = new KeyPair(publicKey);

        // Act
        boolean result = keyPair.canSign(signatureHint);

        // Assert
        assertFalse(result);
    }

    @Test
    public void fromSecretSeed_givenSeed_whenCreatedThenPublicAndPrivateKeysReturned() {
        // Arrange
        byte[] seed = {1, 2, 3};
        KeyPair keyPair = KeyPair.fromSecretSeed(seed);

        // Assert
        assertTrue(keyPair.getPublic() != null);
        assertTrue(keyPair.getPrivate() != null);
    }

    @Test
    public void fromAccountid_givenAccountId_whenCreatedThenPublicAndPrivateKeysReturned() {
        // Arrange
        String accountId = "account-id";
